import{_ as a,o as s,c as l,a3 as i}from"./chunks/framework.Cc-oPviL.js";const u=JSON.parse('{"title":"30 天路线图","description":"","frontmatter":{},"headers":[],"relativePath":"bagu/plan/01.md","filePath":"bagu/plan/01.md"}'),e={name:"bagu/plan/01.md"};function o(n,t,h,d,c,r){return s(),l("div",null,[...t[0]||(t[0]=[i(`<h1 id="_30-天路线图" tabindex="-1">30 天路线图 <a class="header-anchor" href="#_30-天路线图" aria-label="Permalink to &quot;30 天路线图&quot;">​</a></h1><blockquote><p>目标不是&quot;背完&quot;，是<strong>建立骨架 + 能讲清主干 + 接得住两层追问</strong>。 1 个月做不到精通，所以这里砍掉了冷门考点。想全面，看文末的延伸路线。</p></blockquote><div class="tip custom-block"><p class="custom-block-title">配合网站使用</p><p>路线图定的是<strong>学习顺序和每周目标</strong>；每天具体做什么看首页「今日计划」：先复习到期卡，再学下一篇。每篇读完勾验收清单，然后点顶部「练本篇」。</p></div><h2 id="一、四阶段总览" tabindex="-1">一、四阶段总览 <a class="header-anchor" href="#一、四阶段总览" aria-label="Permalink to &quot;一、四阶段总览&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>W1 操作系统 --+</span></span>
<span class="line"><span>              +-&gt; 你知道了&quot;程序跑起来时，机器在忙什么&quot;</span></span>
<span class="line"><span>W2 计算机网络 -+</span></span>
<span class="line"><span>              +-&gt; 你知道了&quot;两台机器之间怎么说话&quot;</span></span>
<span class="line"><span>W3 数据结构 --+</span></span>
<span class="line"><span>              +-&gt; 你知道了&quot;数据怎么摆放才不慢&quot;</span></span>
<span class="line"><span>W4 数据库 ----+</span></span>
<span class="line"><span>              +-&gt; 你知道了&quot;数据怎么存下来还不乱&quot;</span></span>
<span class="line"><span>                    v</span></span>
<span class="line"><span>              串联：一次请求把四块全串起来</span></span></code></pre></div><p>四块不是并列的四门课，是<strong>同一个系统的四个视角</strong>：</p><ul><li>操作系统管「一台机器内部」</li><li>网络管「机器与机器之间」</li><li>数据结构管「数据在内存里怎么摆」</li><li>数据库管「数据在磁盘上怎么存、怎么并发访问」</li></ul><p>学每一块时都问一句：<strong>这块和上一块的接口在哪？</strong> 接口就是&quot;连接&quot;。</p><h2 id="二、每周安排" tabindex="-1">二、每周安排 <a class="header-anchor" href="#二、每周安排" aria-label="Permalink to &quot;二、每周安排&quot;">​</a></h2><table tabindex="0"><thead><tr><th>周次</th><th>模块</th><th>每日投入</th><th>学几天</th><th>复盘日</th></tr></thead><tbody><tr><td>W1</td><td>操作系统（5 篇 + 导读）</td><td>1.5h</td><td>6</td><td>第 7 天</td></tr><tr><td>W2</td><td>计算机网络（5 篇 + 导读）</td><td>1.5h</td><td>6</td><td>第 14 天</td></tr><tr><td>W3</td><td>数据结构与算法（5 篇 + 导读）</td><td>1.5h</td><td>6</td><td>第 21 天</td></tr><tr><td>W4</td><td>数据库（5 篇 + 导读）+ 串联 3 篇</td><td>2h</td><td>7</td><td>第 28 天并入</td></tr></tbody></table><p>每日固定三段，不要合并：</p><table tabindex="0"><thead><tr><th>段</th><th>时长</th><th>做什么</th><th>为什么</th></tr></thead><tbody><tr><td>复习</td><td>15min</td><td><strong>合上书</strong>回忆昨天那篇的主干，说不出来的地方再翻</td><td>主动回忆比重读有效 3 倍</td></tr><tr><td>新学</td><td>60min</td><td>精读当天篇目，边读边在纸上画图</td><td>画图会暴露&quot;以为懂了&quot;的地方</td></tr><tr><td>输出</td><td>15min</td><td>用自己的话写 3 句：它解决什么麻烦 / 怎么做的 / 不用会怎样</td><td>写不出来 = 没懂</td></tr></tbody></table><h2 id="三、每周验收-可判定-不是-理解了" tabindex="-1">三、每周验收（可判定，不是&quot;理解了&quot;） <a class="header-anchor" href="#三、每周验收-可判定-不是-理解了" aria-label="Permalink to &quot;三、每周验收（可判定，不是&quot;理解了&quot;）&quot;">​</a></h2><h3 id="w1-·-操作系统" tabindex="-1">W1 · 操作系统 <a class="header-anchor" href="#w1-·-操作系统" aria-label="Permalink to &quot;W1 · 操作系统&quot;">​</a></h3><ul><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="0"> 能在纸上画出进程 5 状态转换图，每条箭头说出触发条件</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="1"> 能说出虚拟内存解决的两个具体问题，各举一个不这么做会出的事故</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="2"> 能解释 <code>epoll</code> 相比 <code>select</code> 强在哪，说出具体机制差异（不是&quot;更高效&quot;三个字）</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="3"> 能说清一次系统调用里用户态和内核态各做了什么</li></ul><h3 id="w2-·-计算机网络" tabindex="-1">W2 · 计算机网络 <a class="header-anchor" href="#w2-·-计算机网络" aria-label="Permalink to &quot;W2 · 计算机网络&quot;">​</a></h3><ul><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="4"> 不看资料，口述&quot;输入 URL 到收到响应&quot;全链路，每层说出至少 1 个关键机制</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="5"> 能解释三次握手为什么不是两次、四次挥手为什么不是三次</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="6"> 能说清 TIME_WAIT 存在的两个理由</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="7"> 能说清 HTTPS 相比 HTTP 多做了什么，证书在其中解决什么问题</li></ul><h3 id="w3-·-数据结构与算法" tabindex="-1">W3 · 数据结构与算法 <a class="header-anchor" href="#w3-·-数据结构与算法" aria-label="Permalink to &quot;W3 · 数据结构与算法&quot;">​</a></h3><ul><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="8"> 能说清每种结构&quot;为什么存在&quot;，而不是背定义</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="9"> 能手写二分查找且边界不出错（含 left&lt;=right 与 left&lt;right 两种写法）</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="10"> 能手写快排并说清为什么最坏是 O(n²)、怎么避免</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="11"> 能解释哈希表扩容为什么是 2 倍、为什么用 2 的幂做取模优化</li></ul><h3 id="w4-·-数据库" tabindex="-1">W4 · 数据库 <a class="header-anchor" href="#w4-·-数据库" aria-label="Permalink to &quot;W4 · 数据库&quot;">​</a></h3><ul><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="12"> 能说清为什么用 B+ 树而不是 B 树、不是红黑树、不是哈希</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="13"> 能把 ACID 四个字母分别对应到具体实现机制（日志、锁、MVCC）</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="14"> 能说清 MVCC 靠什么实现、解决了什么问题、undo log 在里面扮演什么角色</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="15"> 能对着一条慢 SQL 说出排查顺序（不是背&quot;加索引&quot;）</li></ul><h2 id="四、进度落后了怎么办" tabindex="-1">四、进度落后了怎么办 <a class="header-anchor" href="#四、进度落后了怎么办" aria-label="Permalink to &quot;四、进度落后了怎么办&quot;">​</a></h2><p>按这个顺序砍，不要平均用力：</p><ol><li><strong>先砍导读篇</strong>（00-导读），它只是地图，跳过不影响主干。</li><li><strong>再砍算法篇的代码细节</strong>，保留&quot;为什么用这种结构&quot;的判断。</li><li><strong>绝对不砍</strong>：进程线程、TCP 连接、索引原理、事务隔离。这四块是追问重灾区。</li></ol><p>时间只有半个月的话，就学这四篇，其余全部跳过。</p><h2 id="五、30-天之后-第-2-3-个月延伸" tabindex="-1">五、30 天之后（第 2-3 个月延伸） <a class="header-anchor" href="#五、30-天之后-第-2-3-个月延伸" aria-label="Permalink to &quot;五、30 天之后（第 2-3 个月延伸）&quot;">​</a></h2><p>这一个月只是把骨架立起来。后面按这个顺序加肉：</p><p><strong>第 2 个月 · 往深里挖</strong></p><ul><li>语言层：内存模型、GC、并发原语（Java 的话就是 JMM / GC / synchronized / AQS）</li><li>框架层：一个 Web 框架的启动流程与请求处理链路</li><li>中间件：Redis（数据结构 + 持久化 + 缓存三问）、消息队列（为什么需要、怎么保证不丢）</li></ul><p><strong>第 3 个月 · 往实战转</strong></p><ul><li>项目复盘：把做过的项目按&quot;难点 - 方案 - 取舍 - 结果&quot;重写成 3 个故事</li><li>题量训练：算法保持每周 10 题，重点在&quot;能讲清思路&quot;而不是 AC</li><li>模拟面试：找人或录音，重点练<strong>被追问时的反应</strong>，不是背答案</li></ul><p><strong>贯穿始终的一件事</strong>：每学一个新概念，回到 <a href="/study-hub/bagu/summary/00">一张图串起全部：一次请求的完整旅程</a>，看它挂在哪一层。挂不上去，说明还没真懂。</p><h2 id="六、判断自己真懂了的三个信号" tabindex="-1">六、判断自己真懂了的三个信号 <a class="header-anchor" href="#六、判断自己真懂了的三个信号" aria-label="Permalink to &quot;六、判断自己真懂了的三个信号&quot;">​</a></h2><ol><li>能<strong>不用术语</strong>把它讲明白（用了术语只是把不懂转述了一遍）。</li><li>能说出<strong>不这么做会怎么坏</strong>（说不出坏处，说明只是记住了结论）。</li><li>能把它<strong>接到另一个模块</strong>上（接不上，说明是孤立记忆，两周就忘）。</li></ol><p>三个都做到，这篇可以永久划掉。</p><h2 id="✅-验收清单" tabindex="-1">✅ 验收清单 <a class="header-anchor" href="#✅-验收清单" aria-label="Permalink to &quot;✅ 验收清单&quot;">​</a></h2><ul><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="16"> 能说出四个模块各自管什么，以及它们之间的接口在哪（机器内部 / 机器之间 / 内存里 / 磁盘上）</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="17"> 能说出每日三段各多久、各自的作用（为什么&quot;复习&quot;必须合上书）</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="18"> 能说出&quot;进度落后时先砍什么、绝对不砍什么&quot;，并解释为什么那四篇不能砍</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="19"> 能说出判断&quot;真懂了&quot;的三个信号，并拿昨天学过的一个概念自测一遍</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="20"> 合上书，用自己的话讲 3 分钟，中途不卡壳</li></ul>`,37)])])}const k=a(e,[["render",o]]);export{u as __pageData,k as default};
